     6  /**
     7   * Main procedure for standalone fuzzing engine.
     8   *
     9   * Reads filenames from the argument array. For each filename, read the file
    10   * into memory and then call the fuzzing interface with the data.
    11   */
    12  int main(int argc, char **argv)
    13  {
    14    int ii;
    15    for(ii = 1; ii < argc; ii++)
    16    {
    17      FILE *infile;
    18      printf("[%s] ", argv[ii]);
    19
    20      /* Try and open the file. */
    21      infile = fopen(argv[ii], "rb");
    22      if(infile)
    23      {
    24        uint8_t *buffer = NULL;
    25        size_t buffer_len;
    26
    27        printf("Opened.. ");
    28
    29        /* Get the length of the file. */
    30        fseek(infile, 0L, SEEK_END);
    31        buffer_len = ftell(infile);
    32
    33        /* Reset the file indicator to the beginning of the file. */
    34        fseek(infile, 0L, SEEK_SET);
    35
    36        /* Allocate a buffer for the file contents. */
    37        buffer = (uint8_t *)calloc(buffer_len, sizeof(uint8_t));
    38        if(buffer)
    39        {
    40          /* Read all the text from the file into the buffer. */
    41          fread(buffer, sizeof(uint8_t), buffer_len, infile);
    42          printf("Read %zu bytes, fuzzing.. ", buffer_len);
    43
    44          /* Call the fuzzer with the data. */
    45          LLVMFuzzerTestOneInput(buffer, buffer_len);
    46
    47          printf("complete.");
    48
    49          /* Free the buffer as it's no longer needed. */
    50          free(buffer);
    51          buffer = NULL;
    52        }
    53        else
    54        {
    55          fprintf(stderr,
    56                  "[%s] Failed to allocate %zu bytes \n",
    57                  argv[ii],
    58                  buffer_len);
    59        }
    60
    61        /* Close the file as it's no longer needed. */
    62        fclose(infile);
    63        infile = NULL;
    64      }
    65      else
    66      {
    67        /* Failed to open the file. Maybe wrong name or wrong permissions? */
    68        fprintf(stderr, "[%s] Open failed. \n", argv[ii]);
    69      }
    70
    71      printf("\n");
    72    }
    73  }
