   111  static void _libssh2_sha_algo_ctx_init(int sha_algo, void *ctx)
   112  {
   113      if(sha_algo == 512) {
   114          (void)libssh2_sha512_init((libssh2_sha512_ctx*)ctx);
   115      }
   116      else if(sha_algo == 384) {
   117          (void)libssh2_sha384_init((libssh2_sha384_ctx*)ctx);
   118      }
   119      else if(sha_algo == 256) {
   120          (void)libssh2_sha256_init((libssh2_sha256_ctx*)ctx);
   121      }
   122      else if(sha_algo == 1) {
   123          (void)libssh2_sha1_init((libssh2_sha1_ctx*)ctx);
   124      }
   125      else {
   126          assert(0);
   127      }
   128  }
