   130  static void _libssh2_sha_algo_ctx_update(int sha_algo, void *ctx,
   131                                           void *data, size_t len)
   132  {
   133      if(sha_algo == 512) {
   134          libssh2_sha512_ctx *_ctx = (libssh2_sha512_ctx*)ctx;
   135          libssh2_sha512_update(*_ctx, data, len);
   136      }
   137      else if(sha_algo == 384) {
   138          libssh2_sha384_ctx *_ctx = (libssh2_sha384_ctx*)ctx;
   139          libssh2_sha384_update(*_ctx, data, len);
   140      }
   141      else if(sha_algo == 256) {
   142          libssh2_sha256_ctx *_ctx = (libssh2_sha256_ctx*)ctx;
   143          libssh2_sha256_update(*_ctx, data, len);
   144      }
   145      else if(sha_algo == 1) {
   146          libssh2_sha1_ctx *_ctx = (libssh2_sha1_ctx*)ctx;
   147          libssh2_sha1_update(*_ctx, data, len);
   148      }
   149      else {
   150  #ifdef LIBSSH2DEBUG
   151          assert(0);
   152  #endif
   153      }
   154  }
