   156  static void _libssh2_sha_algo_ctx_final(int sha_algo, void *ctx,
   157                                          void *hash)
   158  {
   159      if(sha_algo == 512) {
   160          libssh2_sha512_ctx *_ctx = (libssh2_sha512_ctx*)ctx;
   161          libssh2_sha512_final(*_ctx, hash);
   162      }
   163      else if(sha_algo == 384) {
   164          libssh2_sha384_ctx *_ctx = (libssh2_sha384_ctx*)ctx;
   165          libssh2_sha384_final(*_ctx, hash);
   166      }
   167      else if(sha_algo == 256) {
   168          libssh2_sha256_ctx *_ctx = (libssh2_sha256_ctx*)ctx;
   169          libssh2_sha256_final(*_ctx, hash);
   170      }
   171      else if(sha_algo == 1) {
   172          libssh2_sha1_ctx *_ctx = (libssh2_sha1_ctx*)ctx;
   173          libssh2_sha1_final(*_ctx, hash);
   174      }
   175      else {
   176  #ifdef LIBSSH2DEBUG
   177          assert(0);
   178  #endif
   179      }
   180  }
