   209   * @function diffie_hellman_sha_algo
   210   * @abstract Diffie Hellman Key Exchange, Group Agnostic,
   211   * SHA Algorithm Agnostic
   212   * @result 0 on success, error code on failure
   213   */
   214  static int diffie_hellman_sha_algo(LIBSSH2_SESSION *session,
   215                                     _libssh2_bn *g,
   216                                     _libssh2_bn *p,
   217                                     int group_order,
   218                                     int sha_algo_value,
   219                                     void *exchange_hash_ctx,
   220                                     unsigned char packet_type_init,
   221                                     unsigned char packet_type_reply,
   222                                     unsigned char *midhash,
   223                                     size_t midhash_len,
   224                                     kmdhgGPshakex_state_t *exchange_state)
