   235      else if(sha_algo_value == 256)
   236          digest_len = SHA256_DIGEST_LENGTH;
   237      else if(sha_algo_value == 1)
   238          digest_len = SHA1_DIGEST_LENGTH;
   239      else {
   240          ret = _libssh2_error(session, LIBSSH2_ERROR_PROTO,
   241                               "sha algo value is unimplemented");
   242          goto clean_exit;
   243      }
   244
