   182  static int
   183  fullpacket(LIBSSH2_SESSION * session, int encrypted /* 1 or 0 */ )
   184  {
   185      unsigned char macbuf[MAX_MACSIZE];
   186      struct transportpacket *p = &session->packet;
   187      int rc;
   188      int compressed;
   189      uint32_t seq = session->remote.seqno;
   190
   191      if(session->fullpacket_state == libssh2_NB_state_idle) {
   192          session->fullpacket_macstate = LIBSSH2_MAC_CONFIRMED;
   193          session->fullpacket_payload_len = p->packet_length - 1;
   194
   195          if(encrypted && !CRYPT_FLAG_L(session, INTEGRATED_MAC)) {
   196
   197              /* Calculate MAC hash */
   198              int etm = session->remote.mac->etm;
   199              size_t mac_len = session->remote.mac->mac_len;
   200              if(etm) {
   201                  /* store hash here */
   202                  session->remote.mac->hash(session, macbuf,
   203                                            session->remote.seqno,
   204                                            p->payload, p->total_num - mac_len,
   205                                            NULL, 0,
   206                                            &session->remote.mac_abstract);
   207              }
   208              else {
   209                  /* store hash here */
   210                  session->remote.mac->hash(session, macbuf,
   211                                            session->remote.seqno,
   212                                            p->init, 5,
   213                                            p->payload,
   214                                            session->fullpacket_payload_len,
   215                                            &session->remote.mac_abstract);
   216              }
   217
   218              /* Compare the calculated hash with the MAC we just read from
   219               * the network. The read one is at the very end of the payload
   220               * buffer. Note that 'payload_len' here is the packet_length
   221               * field which includes the padding but not the MAC.
   222               */
   223              if(memcmp(macbuf, p->payload + p->total_num - mac_len, mac_len)) {
   224                  _libssh2_debug((session, LIBSSH2_TRACE_SOCKET,
   225                                 "Failed MAC check"));
   226                  session->fullpacket_macstate = LIBSSH2_MAC_INVALID;
   227
   228              }
   229              else if(etm) {
   230                  /* MAC was ok and we start by decrypting the first block that
   231                     contains padding length since this allows us to decrypt
   232                     all other blocks to the right location in memory
   233                     avoiding moving a larger block of memory one byte. */
   234                  unsigned char first_block[MAX_BLOCKSIZE];
   235                  ssize_t decrypt_size;
   236                  unsigned char *decrypt_buffer;
   237                  int blocksize = session->remote.crypt->blocksize;
   238
   239                  rc = decrypt(session, p->payload + 4,
   240                               first_block, blocksize, FIRST_BLOCK);
   241                  if(rc) {
   242                      return rc;
   243                  }
   244
   245                  /* we need buffer for decrypt */
   246                  decrypt_size = p->total_num - mac_len - 4;
   247                  decrypt_buffer = LIBSSH2_ALLOC(session, decrypt_size);
   248                  if(!decrypt_buffer) {
   249                      return LIBSSH2_ERROR_ALLOC;
   250                  }
   251
   252                  /* grab padding length and copy anything else
   253                     into target buffer */
   254                  p->padding_length = first_block[0];
   255                  if(blocksize > 1) {
   256                      memcpy(decrypt_buffer, first_block + 1, blocksize - 1);
   257                  }
   258
   259                  /* decrypt all other blocks packet */
   260                  if(blocksize < decrypt_size) {
   261                      rc = decrypt(session, p->payload + blocksize + 4,
   262                                   decrypt_buffer + blocksize - 1,
   263                                   decrypt_size - blocksize, LAST_BLOCK);
   264                      if(rc) {
   265                          LIBSSH2_FREE(session, decrypt_buffer);
   266                          return rc;
   267                      }
   268                  }
   269
   270                  /* replace encrypted payload with plain text payload */
   271                  LIBSSH2_FREE(session, p->payload);
   272                  p->payload = decrypt_buffer;
   273              }
   274          }
   275
   276          session->remote.seqno++;
   277
   278          /* ignore the padding */
   279          session->fullpacket_payload_len -= p->padding_length;
   280
   281          /* Check for and deal with decompression */
   282          compressed = session->local.comp &&
   283                       session->local.comp->compress &&
   284                       ((session->state & LIBSSH2_STATE_AUTHENTICATED) ||
   285                        session->local.comp->use_in_auth);
   286
   287          if(compressed && session->remote.comp_abstract) {
   288              /*
   289               * The buffer for the decompression (remote.comp_abstract) is
   290               * initialised in time when it is needed so as long it is NULL we
   291               * cannot decompress.
   292               */
   293
   294              unsigned char *data;
   295              size_t data_len;
   296              rc = session->remote.comp->decomp(session,
   297                                                &data, &data_len,
   298                                                LIBSSH2_PACKET_MAXDECOMP,
   299                                                p->payload,
   300                                                session->fullpacket_payload_len,
   301                                                &session->remote.comp_abstract);
   302              LIBSSH2_FREE(session, p->payload);
   303              if(rc)
   304                  return rc;
   305
   306              p->payload = data;
   307              session->fullpacket_payload_len = data_len;
   308          }
   309
   310          session->fullpacket_packet_type = p->payload[0];
   311
   312          debugdump(session, "libssh2_transport_read() plain",
   313                    p->payload, session->fullpacket_payload_len);
   314
   315          session->fullpacket_state = libssh2_NB_state_created;
   316      }
   317
   318      if(session->fullpacket_state == libssh2_NB_state_created) {
   319          rc = _libssh2_packet_add(session, p->payload,
   320                                   session->fullpacket_payload_len,
   321                                   session->fullpacket_macstate, seq);
   322          if(rc == LIBSSH2_ERROR_EAGAIN)
   323              return rc;
   324          if(rc) {
   325              session->fullpacket_state = libssh2_NB_state_idle;
   326              return rc;
   327          }
   328      }
   329
   330      session->fullpacket_state = libssh2_NB_state_idle;
   331
   332      if(session->kex_strict &&
   333          session->fullpacket_packet_type == SSH_MSG_NEWKEYS) {
   334          session->remote.seqno = 0;
   335      }
   336
   337      return session->fullpacket_packet_type;
   338  }
